window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[34]={"id":"034","numero":34,"titre":"Suites de couches pathologiques","objectifs":[{"id":"34-1","rang":"B","rubrique":"Dépister","titre":"Connaître les éléments cliniques de surveillance pendant les suites de couches","contenu":"<p>Les <span class=\"kw-def\">suites de couches</span> débutent <strong><span class=\"kw-chiffre\">2 h</span> après l’accouchement</strong> (fin du post-partum immédiat) et se terminent par le <span class=\"kw-def\">retour de couches</span> (= reprise des menstruations). Durée moyenne <span class=\"kw-chiffre\">6 semaines</span> (<span class=\"kw-chiffre\">40 jours</span>). Une <span class=\"kw-alerte\">hospitalisation</span> reste possible jusqu’au <span class=\"kw-chiffre\">12ᵉ jour</span> (prise en charge sécurité sociale).</p>\n\n      <p>L’examen quotidien recherche systématiquement les <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands risques</strong> : <span class=\"kw-alerte\">hémorragie</span>, <span class=\"kw-clinique\">hyperthermie</span>, <span class=\"kw-alerte\">thrombose veineuse</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Ce que l’on cherche</th><th>Alarme si…</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Constantes</strong></td>\n            <td>Température (matin/soir), pouls, PA, FR, SpO₂, diurèse</td>\n            <td>T° &gt; <span class=\"kw-chiffre\">38 °C</span> à 2 reprises, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span></td>\n          </tr>\n          <tr>\n            <td><strong>Utérus</strong></td>\n            <td>Hauteur utérine (involution ≈ <span class=\"kw-chiffre\">1 cm</span>/j), tonicité (globe de sécurité), sensibilité à la mobilisation</td>\n            <td>Utérus <strong>mal involué</strong>, <strong>mou</strong>, <strong>douloureux à la mobilisation</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Lochies</strong></td>\n            <td>Quantité, odeur, aspect (sanglantes <span class=\"kw-chiffre\">J1</span>-J3 → séro-sanglantes → séreuses J10)</td>\n            <td><strong>Abondantes</strong>, <strong>malodorantes / fétides</strong>, hémorragiques tardives</td>\n          </tr>\n          <tr>\n            <td><strong>Périnée / cicatrice</strong></td>\n            <td>Épisiotomie, déchirures, cicatrice de césarienne (rougeur, écoulement, désunion)</td>\n            <td><span class=\"kw-alerte\">Abcès</span> ou <strong>hématome de paroi</strong> après césarienne · <strong>désunion</strong> après épisiotomie</td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Montée laiteuse (<span class=\"kw-chiffre\">J2</span>-J3), engorgement, crevasses, mise au sein efficace</td>\n            <td><span class=\"kw-clinique\">Placard</span> <span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-clinique\">fièvre</span> + douleur localisée (lymphangite, galactophorite, <span class=\"kw-clinique\">abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mollets / MI</strong></td>\n            <td>Douleur unilatérale, <span class=\"kw-clinique\">œdème</span>, Homans, <span class=\"kw-clinique\">dyspnée</span></td>\n            <td>Signes de <span class=\"kw-etio\">TVP</span> ou d’<span class=\"kw-etio\">embolie pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mictions / transit</strong></td>\n            <td>Reprise miction spontanée, <span class=\"kw-bio\">BU</span> si signes urinaires, reprise du transit</td>\n            <td>Rétention aiguë, <span class=\"kw-bio\">BU</span> positive, <span class=\"kw-clinique\">constipation</span> opiniâtre</td>\n          </tr>\n          <tr>\n            <td><strong>Vécu psy</strong></td>\n            <td><em>Baby-blues</em> (<span class=\"kw-chiffre\">J3</span>-J10, transitoire) · <span class=\"kw-def\">dépistage</span> <span class=\"kw-def\">dépression</span> du post-partum</td>\n            <td>Symptômes durables &gt; <span class=\"kw-chiffre\">15 j</span>, idées suicidaires, troubles du lien mère-enfant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Mesures préventives systématiques</h4>\n      <ul>\n        <li><strong>Lever précoce</strong> (<span class=\"kw-chiffre\">J0</span>) — prévention MTEV.</li>\n        <li><strong>Bas de contention</strong> de <span class=\"kw-chiffre\">classe 2</span> chez toutes les accouchées.</li>\n        <li><strong><span class=\"kw-ttt\">HBPM</span> prophylactique</strong> selon le niveau de risque MTEV (voir obj-6).</li>\n        <li><strong>Ig anti-D</strong> si mère Rh- et enfant Rh+ : <span class=\"kw-chiffre\">200 µg</span> IM dans les <span class=\"kw-chiffre\">72 h</span> post-accouchement.</li>\n        <li><strong>Vaccinations à rattraper</strong> en post-partum : rubéole (si non immune), coqueluche, ROR (CI pendant <span class=\"kw-ci\">grossesse</span> mais OK en PP), varicelle.</li>\n        <li><strong>Rééducation périnéale</strong> prescrite à la visite postnatale (<span class=\"kw-chiffre\">6-8 semaines</span>).</li>\n        <li><strong>Contraception du post-partum</strong> proposée avant la sortie (cf. item 31 / 36).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute <span class=\"kw-clinique\">fièvre</span> &gt; <span class=\"kw-chiffre\">38 °C</span>, toute douleur de mollet unilatérale, toute hémorragie ou anomalie des lochies en suites de couches doit déclencher <em>immédiatement</em> la triade diagnostique : <strong>endométrite ? thrombose ? hémorragie ?</strong> Ces 3 entités dominent la morbi-<span class=\"kw-def\">mortalité</span> maternelle du post-partum.\n      </div>","frequence":2},{"id":"34-2","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une hyperthermie pendant les suites de couches en fonction de l’étiologie","contenu":"<p>L’<span class=\"kw-clinique\">hyperthermie</span> du post-partum (T° &gt; <span class=\"kw-chiffre\">38 °C</span>) est <strong>fréquente</strong> et impose une démarche étiologique structurée. La <span class=\"kw-def\">montée laiteuse</span> (<span class=\"kw-chiffre\">J2</span>-J3, fébricule modéré, seins tendus bilatéraux, pas d’autre signe) est un <strong>diagnostic d’élimination</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies à connaître (ordre décroissant)</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Tableau évocateur</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Endométrite aiguë du PP</span></strong><br><em>1ʳᵉ cause</em></td>\n            <td>\n              <ul>\n                <li>Début <span class=\"kw-chiffre\">J3-J5</span> (rarement avant)</li>\n                <li><span class=\"kw-clinique\">Fièvre</span> modérée ≈ <span class=\"kw-chiffre\">38 °C</span></li>\n                <li><strong>Douleur à la mobilisation utérine</strong> ⭐ — signe principal</li>\n                <li>Lochies <strong>abondantes et malodorantes</strong> (fétides ± hémorragiques)</li>\n                <li>Utérus <strong>mal involué</strong>, col béant</li>\n                <li><strong>Germes</strong> : infection plurimicrobienne — <span class=\"kw-etio\">SGA</span> (le + redouté), entérobactéries (BGN), <span class=\"kw-etio\">streptocoque</span> B, entérocoques ; anaérobies et intracellulaires (mycoplasme, chlamydia) plus rares</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-bio\">NFS</span>/<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ECBU</span>, examen bactério vaginal, <span class=\"kw-imagerie\">échographie</span> pelvienne (rétention ?) · <span class=\"kw-bio\">Hémocultures</span> si T° &gt; <span class=\"kw-chiffre\">38,5 °C</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Pyélonéphrite aiguë</span></strong> (≠ gravidique)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">frissons</span></li>\n                <li>Douleur lombaire unilatérale</li>\n                <li>Signes urinaires</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-bio\">NFS</span>/<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span>, écho rénale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombophlébite des MI</span></strong></td>\n            <td>\n              <ul>\n                <li>Douleur de mollet unilatérale</li>\n                <li><span class=\"kw-clinique\">Œdème</span>, augmentation du <span class=\"kw-clinique\">diamètre</span></li>\n                <li>Signe de Homans</li>\n                <li><span class=\"kw-clinique\">Fièvre</span> modérée</li>\n              </ul>\n            </td>\n            <td>Écho-<span class=\"kw-imagerie\">doppler veineux</span> MI · <span class=\"kw-bio\">D-dimères</span> <em>peu utiles en PP</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Fièvre</span> <em>persistante</em> sous ATB d’une endométrite</li>\n                <li>Douleurs pelviennes diffuses</li>\n                <li>Tableau souvent atypique</li>\n              </ul>\n            </td>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> pelvienne injectée</strong> — diagnostic de référence</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Complications de l’allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Engorgement</strong> : seins tendus bilatéraux, fébricule</li>\n                <li><strong>Lymphangite</strong> : <span class=\"kw-clinique\">placard</span> rouge triangulaire, <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">39-40 °C</span>, ADP axillaire</li>\n                <li><strong>Galactophorite</strong> : douleur, lait <em>louche</em> au signe de Budin</li>\n                <li><strong><span class=\"kw-clinique\">Abcès</span> du sein</strong> : <span class=\"kw-clinique\">tuméfaction</span> fluctuante, <span class=\"kw-clinique\">fièvre</span> élevée</li>\n              </ul>\n            </td>\n            <td>Clinique · <span class=\"kw-imagerie\">échographie</span> mammaire si suspicion d’<span class=\"kw-clinique\">abcès</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Infection du site opératoire</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Après césarienne</strong> : <span class=\"kw-clinique\">abcès</span> ou hématome de paroi, écoulement purulent</li>\n                <li><strong>Après épisiotomie</strong> : <strong>désunion de plaie</strong> ± hématome périnéal</li>\n                <li><span class=\"kw-alerte\">Alerte</span> : <span class=\"kw-def\">purpura</span> ou décollement cutané rapidement évolutif → rechercher <strong>SGA</strong> ou <strong>S. aureus</strong></li>\n              </ul>\n            </td>\n            <td>Examen clinique, écho de paroi, prélèvements bactério</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Montée laiteuse</span> <em>(diagnostic d’élimination)</em></td>\n            <td>Fébricule <span class=\"kw-chiffre\">J2</span>-J3 bilatéral, seins tendus, <strong>pas de douleur utérine, pas de signes urinaires, pas de signes de <span class=\"kw-etio\">TVP</span></strong></td>\n            <td>Diagnostic clinique <em>après avoir éliminé les autres causes</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan <span class=\"kw-ttt\">biologique</span> initial systématique</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">CRP</span></strong></li>\n        <li><strong><span class=\"kw-bio\">BU</span> ± <span class=\"kw-bio\">ECBU</span></strong></li>\n        <li><strong>Prélèvement vaginal</strong> (examen bactériologique)</li>\n        <li><strong><span class=\"kw-bio\">Hémocultures</span></strong> si T° &gt; <span class=\"kw-chiffre\">38,5 °C</span> (recherche listeria et SGA notamment)</li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne</strong> à la recherche d’une rétention placentaire</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Endométrite à SGA ⚠️.</strong> <span class=\"kw-etio\">Streptocoque</span> du groupe A = germe le plus redouté du post-partum (tableau toxinique pouvant évoluer en quelques heures vers le <span class=\"kw-def\">choc septique</span>). Y penser devant toute endométrite d’<span class=\"kw-clinique\">évolution</span> rapide, <span class=\"kw-clinique\">hyperthermie</span> élevée, douleurs intenses, signes cutanés. <span class=\"kw-bio\">Hémocultures</span> + écouvillonnage vaginal pour test rapide. <span class=\"kw-alerte\">Hospitalisation</span>, β-lactamines à forte dose ± <span class=\"kw-ttt\">clindamycine</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Si <span class=\"kw-clinique\">fièvre</span> persistante sous ATB :</strong> évoquer en priorité <strong>2 diagnostics</strong> →\n        <ul>\n          <li><strong>Thrombophlébite pelvienne</strong> associée (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> injectée).</li>\n          <li><strong>Rétention de fragments placentaires</strong> (<span class=\"kw-imagerie\">échographie</span> pelvienne).</li>\n        </ul>\n      </div>","frequence":10},{"id":"34-3","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une hyperthermie pendant les suites de couches en fonction de l’étiologie","contenu":"<p>La prise en charge est <strong>étiologique</strong>. <span class=\"kw-alerte\">Hospitalisation</span> habituelle pour toute <span class=\"kw-clinique\">fièvre</span> du post-partum &gt; <span class=\"kw-chiffre\">38,5 °C</span> ou avec <span class=\"kw-alerte\">signes de gravité</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Endométrite aiguë du PP</h4>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Orientation</strong></td>\n            <td><span class=\"kw-alerte\">Hospitalisation</span> 🏥</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Antibiothérapie</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> pendant <span class=\"kw-chiffre\">5-10 jours</span></li>\n                <li>Voie IV initialement, relai per os après normalisation thermique</li>\n                <li>Adaptation à l’<span class=\"kw-bio\">antibiogramme</span> (prélèvement vaginal, <span class=\"kw-bio\">hémocultures</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utérotoniques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Oxytocine</span> ou <span class=\"kw-ttt\">misoprostol</span> pour favoriser la rétraction utérine</li>\n                <li><strong>Non systématique</strong>, à débuter en cas d’<strong>endométrite <span class=\"kw-etio\">hémorragique</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li>Généralement rapidement favorable sous traitement adapté</li>\n                <li><strong>Si <span class=\"kw-clinique\">fièvre</span> persistante</strong> → 2 diagnostics prioritaires :\n                  <ul>\n                    <li>Thrombophlébite pelvienne (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> injectée)</li>\n                    <li>Rétention de fragments placentaires (<span class=\"kw-imagerie\">échographie</span> pelvienne)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Autres étiologies — schémas thérapeutiques</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pyélonéphrite</span> aiguë</strong></td>\n            <td>\n              <ul>\n                <li>C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> IV (<span class=\"kw-ttt\">céfotaxime</span> / <span class=\"kw-ttt\">ceftriaxone</span>) ± aminoside</li>\n                <li>Relai per os adapté à l’<span class=\"kw-bio\">antibiogramme</span> · durée <span class=\"kw-chiffre\">10-14 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombophlébite des MI</strong></td>\n            <td><span class=\"kw-ttt\">HBPM</span> curative + bas de contention <span class=\"kw-chiffre\">classe 3</span> (cf. obj-6)</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombophlébite pelvienne</strong></td>\n            <td>\n              <ul>\n                <li><strong>ATB IV adaptée</strong> (poursuite/escalade)</li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span class=\"kw-ttt\">AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Engorgement / lymphangite</strong></td>\n            <td>\n              <ul>\n                <li>Poursuite de l’<span class=\"kw-ci\">allaitement</span> (sauf <span class=\"kw-clinique\">abcès</span> patent)</li>\n                <li>Tétées fréquentes, vidange complète, <span class=\"kw-ttt\">AINS</span> local / <span class=\"kw-ttt\">paracétamol</span></li>\n                <li>Si lymphangite : ATB anti-staphylococcique (oxacilline, cloxacilline) <span class=\"kw-chiffre\">7-10 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Galactophorite</strong></td>\n            <td>ATB anti-staph + suspension transitoire de l’<span class=\"kw-ci\">allaitement</span> du côté atteint</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Abcès</span> du sein</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-ttt\">Drainage</span> chirurgical</strong> ou <span class=\"kw-ttt\">ponction</span> écho-guidée</li>\n                <li>ATB anti-staphylococcique</li>\n                <li><span class=\"kw-ci\">Allaitement</span> <span class=\"kw-ci\">contre-indiqué</span> côté atteint pendant la phase aiguë</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infection de cicatrice de césarienne</strong></td>\n            <td>\n              <ul>\n                <li>Évacuation d’un hématome / mise à plat d’un <span class=\"kw-clinique\">abcès</span></li>\n                <li>ATB anti-staphylococcique adaptée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Désunion d’épisiotomie</strong></td>\n            <td>\n              <ul>\n                <li>Soins locaux antiseptiques, cicatrisation dirigée</li>\n                <li><span class=\"kw-ttt\">Reprise chirurgicale</span> différée si nécessaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Montée laiteuse</span></td>\n            <td>Pas d’ATB — <span class=\"kw-def\">surveillance</span> simple, <span class=\"kw-ttt\">paracétamol</span>, vidange du sein</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Signal d’alarme.</strong> Toute infection cutanée rapidement évolutive avec <strong><span class=\"kw-def\">purpura</span></strong> ou <strong>décollement</strong> doit faire évoquer et traiter en <span class=\"kw-alerte\">urgence</span> un <span class=\"kw-etio\">SGA</span> ou un <span class=\"kw-alerte\">S. aureus</span> (risque de <span class=\"kw-alerte\">fasciite nécrosante</span> / <span class=\"kw-def\">sepsis</span> foudroyant) : <span class=\"kw-alerte\">hospitalisation</span>, β-lactamines IV à forte dose ± <span class=\"kw-ttt\">clindamycine</span>, avis chirurgical.\n      </div>","frequence":0},{"id":"34-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","contenu":"<p>Hémorragie du post-partum (HPP) = perte sanguine <span class=\"kw-chiffre\">≥ 500 mL</span> ⭐. <strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> en France (évitable dans <span class=\"kw-chiffre\">80-90 %</span> des cas). Distinguer 3 fenêtres temporelles :</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 140\" role=\"img\" aria-label=\"Frise des trois fenêtres temporelles de l'hémorragie génitale du post-partum : avant 2 heures, hémorragie de la délivrance par atonie utérine (plus de 50 % des cas) ; de 2 à 24 heures, HPP précoce par atonie utérine, rétention placentaire partielle ou plaie de la filière génitale ; de J1 à M3, HPP tardive ou secondaire par endométrite, retour de couches hémorragique ou choriocarcinome avec dosage hCG.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Hémorragie du post-partum — 3 fenêtres temporelles</text>\n          <rect class=\"fb-red\" x=\"10\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"96\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">&lt;<span class=\"kw-chiffre\"> 2 h</span></text>\n          <text class=\"tx-red\" x=\"96\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Hémorragie de la délivrance</text>\n          <text class=\"tx-red\" x=\"96\" y=\"101\" text-anchor=\"middle\" font-size=\"8.5\">Atonie utérine (&gt;<span class=\"kw-chiffre\"> 50 %</span>)</text>\n          <rect class=\"fb-amber\" x=\"194\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\"><span class=\"kw-chiffre\">2 – 24 h</span></text>\n          <text class=\"tx-amber\" x=\"280\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">HPP précoce</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"94\" font-size=\"8.5\">• Atonie utérine</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"107\" font-size=\"8.5\">• Rétention placentaire</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"120\" font-size=\"8.5\">• Plaie de la filière</text>\n          <rect class=\"fb-amber\" x=\"378\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"464\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\"><span class=\"kw-chiffre\">J1</span> – M3</text>\n          <text class=\"tx-amber\" x=\"464\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">HPP tardive / secondaire</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"94\" font-size=\"8.5\">• Endométrite</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"107\" font-size=\"8.5\">• Retour de couches hém.</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"120\" font-size=\"8.5\">• Choriocarcinome (→ hCG)</text>\n          <line class=\"ln\" x1=\"184\" y1=\"84\" x2=\"191\" y2=\"84\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"194,84 188,80.5 188,87.5\"/>\n          <line class=\"ln\" x1=\"368\" y1=\"84\" x2=\"375\" y2=\"84\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"378,84 372,80.5 372,87.5\"/>\n        </svg>\n        <figcaption>Les bornes datent l’hémorragie — &lt;<span class=\"kw-chiffre\"> 2 h</span> délivrance,<span class=\"kw-chiffre\"> 2-24 h</span> précoce, &gt;<span class=\"kw-chiffre\"> 24 h</span> (J1-M3) tardive — et chaque fenêtre a ses causes propres.</figcaption>\n      </figure>\n\n      <table >\n        <thead>\n          <tr><th>Fenêtre</th><th>Définition</th><th>Causes dominantes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hémorragie de la délivrance</strong></td>\n            <td>Post-partum immédiat <span class=\"kw-chiffre\">&lt; 2 h</span> après la naissance</td>\n            <td><strong><span class=\"kw-etio\">Atonie utérine</span></strong> (&gt; <span class=\"kw-chiffre\">50 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>HPP précoce</strong></td>\n            <td>Entre <span class=\"kw-chiffre\">2 h et 24 h</span></td>\n            <td>\n              <ul>\n                <li>Atonie utérine</li>\n                <li>Rétention placentaire partielle (cotylédons, membranes)</li>\n                <li>Plaie de la filière génitale</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>HPP tardive / secondaire</strong></td>\n            <td>Entre <span class=\"kw-chiffre\">J1 et M3</span></td>\n            <td>\n              <ul>\n                <li>Endométrite <span class=\"kw-etio\">hémorragique</span></li>\n                <li>Retour de couches <span class=\"kw-etio\">hémorragique</span></li>\n                <li><span class=\"kw-alerte\">Choriocarcinome</span> (rare, justifie un dosage hCG si bilan négatif)</li>\n                <li>Très rares : faux anévrismes, fistules AV, coagulopathies</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies — démarche diagnostique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Clinique</th><th>Paraclinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Atonie utérine</span></strong><br><em>&gt; <span class=\"kw-chiffre\">50 %</span> des HPP</em></td>\n            <td>\n              <ul>\n                <li>Métrorragies abondantes, sang rouge</li>\n                <li><strong>Absence de globe de sécurité</strong> : utérus mou, non rétracté, dépassant l’ombilic</li>\n                <li>Pas de <span class=\"kw-clinique\">fièvre</span>, pas de lochies malodorantes</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-imagerie\">Échographie</span> pelvienne pour <strong>éliminer une rétention</strong> (membranes, cotylédons)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Rétention placentaire partielle</span></strong></td>\n            <td>\n              <ul>\n                <li>Pas de signe clinique spécifique ❌</li>\n                <li>Hémorragie persistante malgré utérotoniques</li>\n                <li>Peut favoriser une atonie ou une endométrite</li>\n              </ul>\n            </td>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne ⭐</strong> = examen de référence (systématique si <span class=\"kw-clinique\">hyperthermie</span> ou hémorragie en PP)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Plaie de la filière génitale</span></strong></td>\n            <td>\n              <ul>\n                <li>Saignement <strong>de sang rouge vif</strong></li>\n                <li>Utérus bien rétracté (globe de sécurité présent)</li>\n                <li>Déchirure du col, du vagin, du périnée</li>\n              </ul>\n            </td>\n            <td><strong>Inspection sous valves</strong> systématique des voies génitales basses</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Endométrite hémorragique</span></strong></td>\n            <td>\n              <ul>\n                <li>Tableau d’endométrite (<span class=\"kw-clinique\">fièvre</span>, douleur à la mobilisation utérine, lochies fétides)</li>\n                <li>+ saignement génital surajouté</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-bio\">NFS</span>/<span class=\"kw-bio\">CRP</span>, prélèvement vaginal, écho pelvienne (rétention ?)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Retour de couches hémorragique</span></strong></td>\n            <td>\n              <ul>\n                <li>Hémorragie <strong>brutale</strong> plusieurs semaines après l’accouchement</li>\n                <li>Cause : carence œstrogénique ou contraception microprogestative précoce</li>\n                <li>Clinique pauvre : apyrétique, indolore, col fermé, utérus involué</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-imagerie\">Échographie</span> : utérus vide, endomètre fin · élimine endométrite ou rétention</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Choriocarcinome</span></strong></td>\n            <td>Hémorragie tardive <strong>inexpliquée</strong> malgré bilan négatif</td>\n            <td><strong>Dosage hCG</strong> systématique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan paraclinique systématique devant une HPP &gt; <span class=\"kw-chiffre\">2 h</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, bilan d’hémostase</strong> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span> → <span class=\"kw-alerte\">CIVD</span> ?)</li>\n        <li><strong>Groupe-rhésus, RAI &lt; <span class=\"kw-chiffre\">3 jours</span></strong></li>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne</strong></li>\n        <li><strong>Dosage hCG</strong> si hémorragie tardive inexpliquée (choriocarcinome)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Facteurs de risque</span> d’HPP — dogme.</strong> Aucun facteur retrouvé dans <span class=\"kw-chiffre\">50 %</span> des cas : <em>aucun accouchement n’est « à bas risque »</em>.<br>\n        <strong><span class=\"kw-def\">Terrain</span></strong> : grande multiparité, utérus cicatriciel, ATCD HPP.<br>\n        <strong><span class=\"kw-ci\">Grossesse</span></strong> : surdistension (macrosomie, hydramnios, gémellaire), fibromes, placenta praevia, chorioamniotite.<br>\n        <strong>Accouchement</strong> : travail déclenché, très rapide ou prolongé, épisiotomie / déchirure périnéale, forceps / ventouse, absence d’utérotoniques systématiques.\n      </div>","frequence":0},{"id":"34-5","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","contenu":"<p>Toute HPP est une <span class=\"kw-alerte\">urgence vitale</span>. La prise en charge est <strong>simultanément maternelle (hémodynamique)</strong> et <strong>obstétricale (geste hémostatique)</strong>, escaladée par paliers de 15-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>30</span> min</span>utes.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragie de la délivrance (post-partum immédiat &lt; <span class=\"kw-chiffre\">2 h</span>)</h4>\n      <table >\n        <thead><tr><th>Temps</th><th>Actions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ temps</strong></td>\n            <td>Prévenir <strong>tous les intervenants</strong> (anesthésiste, sage-femme, obstétricien) sans délai</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ temps</strong></td>\n            <td>\n              <ul>\n                <li>Monitorage (pouls, PA, SpO₂)</li>\n                <li>VVP de gros calibre, remplissage cristalloïdes</li>\n                <li>Vérification groupe + RAI &lt; <span class=\"kw-chiffre\">3 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ temps — geste obstétrical</strong></td>\n            <td>\n              <ul>\n                <li>Si hémorragie <strong>avant</strong> expulsion du placenta → <strong>délivrance artificielle</strong> en <span class=\"kw-alerte\">urgence</span></li>\n                <li>Si hémorragie <strong>après</strong> expulsion → <strong>révision utérine</strong> d’emblée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4ᵉ temps — hémostase</strong></td>\n            <td>\n              <ul>\n                <li><strong>Massage utérin énergique ⭐</strong> jusqu’à obtenir un <strong>globe tonique</strong></li>\n                <li><strong>Inspection sous valves</strong> → éliminer une déchirure cervicale / vaginale</li>\n                <li><span class=\"kw-ttt\">Oxytocine IVL 10 UI</span>, renouvelable 1×</li>\n                <li>Sac collecteur sous les fesses (estimation des pertes)</li>\n                <li>Sondage urinaire à demeure (vessie vide = bon globe)</li>\n                <li>Suture des déchirures périnéales éventuelles</li>\n                <li><span class=\"kw-ttt\">Antibioprophylaxie</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si persistance des saignements à <span class=\"kw-chiffre\">15-30 min</span> :</strong>\n        <ul>\n          <li><span class=\"kw-ttt\">Sulprostone</span> (prostaglandine) à la seringue électrique, puis relai oxytocine <span class=\"kw-chiffre\">2 h</span></li>\n          <li><span class=\"kw-ttt\">Acide tranexamique</span> <span class=\"kw-chiffre\">1 g</span> IV</li>\n          <li>VVP gros calibre, <span class=\"kw-ttt\">oxygénothérapie</span>, remplissage par macromolécules</li>\n          <li><strong>Transfusion CGR + PFC</strong> selon pertes et coagulation</li>\n          <li><span class=\"kw-bio\">NFS</span> + bilan d’hémostase en <span class=\"kw-alerte\">urgence</span> (recherche <span class=\"kw-alerte\">CIVD</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si hémorragie persistante malgré la PEC initiale :</strong>\n        <ul>\n          <li><strong>Embolisation artérielle sélective</strong> — 3 prérequis : patiente stable, radiologue entraîné disponible, unité d’embolisation à proximité</li>\n          <li><strong><span class=\"kw-ttt\">Chirurgie</span></strong> : ligature des artères utérines / hypogastriques, techniques de compression utérine (B-Lynch, Cho)</li>\n          <li><strong>En dernier recours — hystérectomie d’hémostase</strong>, à ne pas retarder si <span class=\"kw-alerte\">hémodynamique instable</span> ou <span class=\"kw-alerte\">CIVD installée</span></li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragies du post-partum (&gt; <span class=\"kw-chiffre\">2 h</span>) — traitement étiologique</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atonie utérine</strong></td>\n            <td>\n              <ul>\n                <li>Massage utérin + <span class=\"kw-ttt\">utérotoniques</span> (oxytocine, prostaglandines)</li>\n                <li>Si échec → escalade comme HPP de la délivrance</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Rétention placentaire</strong></td>\n            <td>\n              <ul>\n                <li><strong>Révision utérine prudente</strong> (curette mousse sous contrôle échographique — utérus fragile)</li>\n                <li>Résection hystéroscopique parfois</li>\n                <li><strong><span class=\"kw-ttt\">Antibioprophylaxie</span></strong> systématique</li>\n                <li>Si hémorragie importante : <strong>tamponnement intra-utérin</strong> (Bakri) ou embolisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Plaie de la filière génitale</strong></td>\n            <td>Suture après exposition sous valves, au bloc si nécessaire</td>\n          </tr>\n          <tr>\n            <td><strong>Endométrite <span class=\"kw-etio\">hémorragique</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> IV</li>\n                <li><strong>Utérotoniques systématiques</strong> (oxytocine ± misoprostol)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Retour de couches <span class=\"kw-etio\">hémorragique</span></strong></td>\n            <td>\n              <ul>\n                <li>Pilule œstrogénique (en l’absence de CI)</li>\n                <li><span class=\"kw-def\">Surveillance</span> simple si pertes modérées</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Choriocarcinome</strong></td>\n            <td>Dosage hCG → orientation oncologique spécialisée (<span class=\"kw-ttt\">chimiothérapie</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Prévention systématique de l’HPP — APO.</strong> <span class=\"kw-ttt\">Oxytocine 5-10 UI IVL</span> dès la sortie de l’enfant, sac de recueil dès l’expulsion, <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle de travail, délivrance artificielle si non-décollement placentaire à <span class=\"kw-chiffre\">30 min</span>.\n      </div>","frequence":1},{"id":"34-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","contenu":"<p>Le post-partum est un <strong><span class=\"kw-def\">facteur de risque</span> transitoire majeur de MTEV</strong>, surtout pendant les <span class=\"kw-chiffre\">8 premières semaines</span>. Quatre formes cliniques à reconnaître.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Facteurs favorisants</h4>\n      <ul>\n        <li>Âge <span class=\"kw-chiffre\">&gt; 35 ans</span>, multiparité, <span class=\"kw-etio\">tabac</span></li>\n        <li><span class=\"kw-etio\">Obésité</span>, varices, affections cardiaques</li>\n        <li>ATCD personnel de MTEV, thrombophilie</li>\n        <li>Accouchement dystocique ou <strong>césarienne</strong> (surtout en <span class=\"kw-alerte\">urgence</span>)</li>\n        <li>Procréation médicalement assistée</li>\n        <li><strong>Hémorragie du post-partum</strong></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Formes cliniques</h4>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Tableau évocateur</th><th>Examen de référence</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombose veineuse superficielle</span></strong></td>\n            <td>\n              <ul>\n                <li>Cordon induré douloureux sur trajet variqueux</li>\n                <li>Inflammation locale, pas de <span class=\"kw-clinique\">fièvre</span> élevée</li>\n              </ul>\n            </td>\n            <td>Clinique · écho-<span class=\"kw-imagerie\">doppler veineux</span> (élimine extension profonde)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombose veineuse profonde (MI)</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Douleur de mollet unilatérale</strong></li>\n                <li><span class=\"kw-clinique\">Œdème</span>, augmentation du <span class=\"kw-clinique\">diamètre</span>, perte du ballant</li>\n                <li>Signe de Homans</li>\n                <li>Fébricule modéré, <span class=\"kw-clinique\">tachycardie</span> inexpliquée</li>\n              </ul>\n            </td>\n            <td><strong>Écho-<span class=\"kw-imagerie\">doppler veineux</span> des MI</strong> · <span class=\"kw-bio\">D-dimères</span> <em>peu utiles en PP</em> (élevés physiologiquement)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-clinique\">Fièvre</span> persistante</strong> sous ATB pour endométrite</li>\n                <li>Douleurs pelviennes / lombo-abdominales diffuses</li>\n                <li>Tableau atypique, retardé</li>\n              </ul>\n            </td>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> pelvienne injectée</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Thrombose veineuse cérébrale</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Céphalées</span> inhabituelles, persistantes</li>\n                <li>Crises convulsives, déficit focal</li>\n                <li>Troubles de la conscience, signes d’<span class=\"kw-alerte\">HTIC</span></li>\n              </ul>\n            </td>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> cérébrale + <span class=\"kw-imagerie\">angio-IRM</span> veineuse</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Complication redoutée — <span class=\"kw-etio\">embolie pulmonaire</span></h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Dyspnée</span> brutale, <span class=\"kw-clinique\">douleur thoracique</span>, <span class=\"kw-clinique\">tachycardie</span>, hypoxémie</li>\n        <li><span class=\"kw-alerte\">Toute dyspnée du post-partum est une EP jusqu’à preuve du contraire</span></li>\n        <li>Confirmation : <strong><span class=\"kw-imagerie\">angio-TDM</span> thoracique</strong> (scinti V/Q si CI)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège diagnostique.</strong> En post-partum, les <strong><span class=\"kw-bio\">D-dimères</span></strong> sont physiologiquement élevés et n’ont <em>pas de valeur d’exclusion</em>. La décision diagnostique repose donc directement sur la <strong>probabilité clinique + imagerie</strong> (écho-<span class=\"kw-imagerie\">doppler veineux</span>, <span class=\"kw-imagerie\">angio-TDM</span>).\n      </div>","frequence":1},{"id":"34-7","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une thrombose veineuse dans le post-partum en fonction de l’étiologie","contenu":"<p>Deux axes : <strong>prophylaxie</strong> (stratifiée selon le niveau de risque MTEV) et <strong>traitement curatif</strong> (selon la localisation).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">A. Prophylaxie de la MTEV en post-partum</h4>\n      <table >\n        <thead>\n          <tr><th>Niveau de risque</th><th>Définition</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Risque majeur</span></strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong>MTEV multiples</strong></li>\n                <li><strong>Thrombophilie traitée au long cours</strong> par <span class=\"kw-ttt\">anticoagulant</span> (même avant la <span class=\"kw-ci\">grossesse</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Bas de contention</li>\n                <li><strong><span class=\"kw-ttt\">AVK</span> pendant ≥ <span class=\"kw-chiffre\">3 mois</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV lors d’une <span class=\"kw-ci\">grossesse</span> antérieure ou d’un traitement œstrogénique</li>\n                <li>ATCD MTEV + 1 FR <span class=\"kw-ttt\">biologique</span> (déficit AT, SAPL, mutation 20210A homozygote ou <span class=\"kw-alerte\">FV</span> Leiden, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Bas de contention</li>\n                <li><strong><span class=\"kw-ttt\">HBPM</span> à dose prophylactique forte</strong> pendant <span class=\"kw-chiffre\">6-8 semaines</span><br><em><span class=\"kw-ttt\">énoxaparine</span> 4 <span class=\"kw-chiffre\">000 UI</span>/j ou daltéparine 5 <span class=\"kw-chiffre\">000 UI</span>/j</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec FR temporaire au moment de l’épisode antérieur</li>\n                <li>ATCD MTEV + FR <span class=\"kw-ttt\">biologique</span> (autre que ceux du risque élevé)</li>\n                <li>FR <span class=\"kw-ttt\">biologique</span> asymptomatique dépisté dans le cadre d’une MTEV familiale</li>\n                <li><strong>Césarienne en <span class=\"kw-alerte\">urgence</span></strong></li>\n                <li>Césarienne + <span class=\"kw-ttt\">chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de ≥ <span class=\"kw-chiffre\">3 FR faibles</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Bas de contention</li>\n                <li><strong><span class=\"kw-ttt\">HBPM</span> à dose prophylactique forte</strong> pendant <span class=\"kw-chiffre\">6-8 semaines</span> (dose et durée pouvant être réduites selon le niveau de risque)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              &lt; 3 des FR suivants :\n              <ul>\n                <li>Âge &gt;<span class=\"kw-chiffre\"> 35 ans</span>, <span class=\"kw-etio\">obésité</span> (IMC &gt; 30 ou poids &gt;<span class=\"kw-chiffre\"> 80 kg</span>), varices, <span class=\"kw-def\">HTA</span></li>\n                <li>Facteurs obstétricaux : césarienne, multiparité &gt; 4, prééclampsie, alitement strict prolongé, HPP…</li>\n                <li>Maladie thrombogène sous-jacente (<span class=\"kw-def\">syndrome néphrotique</span>, <span class=\"kw-def\">MICI</span> en poussée, infection systémique…)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Bas de contention</li>\n                <li><strong>Pas d’<span class=\"kw-ttt\">anticoagulant</span></strong> ❌</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">B. Traitement curatif selon la localisation</h4>\n      <table >\n        <thead><tr><th>Localisation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Thrombose veineuse superficielle</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">AINS</span> locaux + contention veineuse</li>\n                <li>± Anticoagulation selon extension et localisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Thrombose veineuse profonde</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Anticoagulation curative</strong> (<span class=\"kw-ttt\">HBPM</span>, puis relai <span class=\"kw-ttt\">AVK</span> compatible avec l’<span class=\"kw-ci\">allaitement</span>)</li>\n                <li>Contention veineuse <strong><span class=\"kw-chiffre\">classe 3</span></strong></li>\n                <li>Durée : <span class=\"kw-chiffre\">3-6 mois</span> minimum selon contexte</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombophlébite pelvienne</strong></td>\n            <td>\n              <ul>\n                <li><strong>ATB IV adaptée</strong></li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span class=\"kw-ttt\">AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose veineuse cérébrale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-ttt\">HBPM</span> curative</strong> puis relai <span class=\"kw-ttt\">AVK</span> ≥ <span class=\"kw-chiffre\">6 mois</span></li>\n                <li>± mannitol / anti-épileptique selon signes neurologiques</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">C. Choix de l’<span class=\"kw-ttt\">AVK</span> pendant l’<span class=\"kw-ci\">allaitement</span></h4>\n      <table >\n        <thead><tr><th>Molécule</th><th>Allaitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Fluindione</span></td>\n            <td><span class=\"kw-alerte\">❌ Contre-indiquée</span> — non utilisable pendant l’<span class=\"kw-ci\">allaitement</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Warfarine</span>, <span class=\"kw-ttt\">acénocoumarol</span></td>\n            <td>✅ Possibles — pas de <span class=\"kw-imagerie\">diffusion</span> dans le lait maternel</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> En post-partum la <strong><span class=\"kw-ttt\">warfarine</span></strong> et l’<strong>acénocoumarol</strong> sont les <span class=\"kw-ttt\">AVK</span> de choix si <span class=\"kw-ci\">allaitement</span>, jamais la <span class=\"kw-ttt\">fluindione</span>. Les <span class=\"kw-ttt\">HBPM</span> restent l’option la plus utilisée en pratique en relai initial.\n      </div>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Hémorragie du post-partum immédiat <span class=\"q\">— &lt;<span class=\"kw-chiffre\"> 2 h</span>, <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p>Appel de tous les intervenants sans délai · massage utérin · <span class=\"kw-ttt\">oxytocine IVL 10 UI</span> · escalade par paliers de <span class=\"kw-chiffre\">15-30 min</span></p><ul><li><strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> en France (<span class=\"kw-chiffre\">80-90 %</span> évitable)</li><li>Perte sanguine <span class=\"kw-chiffre\">≥ 500 mL</span> → diagnostic</li><li><span class=\"kw-alerte\">Atonie utérine</span> = cause dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas</li></ul><p><strong>Persistance de l'hémorragie à <span class=\"kw-chiffre\">15-30 min</span></strong></p><p>Si persistance → <strong>embolisation artérielle sélective</strong> (patiente stable) ou <span class=\"kw-ttt\">chirurgie</span> (ligature, compression B-Lynch) · dernier recours : <span class=\"kw-alerte\">hystérectomie d'hémostase</span></p><ul><li><span class=\"kw-ttt\">Sulprostone</span> (seringue électrique) + relai <span class=\"kw-ttt\">oxytocine</span> <span class=\"kw-chiffre\">2 h</span></li><li><span class=\"kw-ttt\">Acide tranexamique</span> <span class=\"kw-chiffre\">1 g</span> IV</li><li>Transfusion <span class=\"kw-ttt\">CGR + PFC</span> si besoin · recherche <span class=\"kw-bio\">CIVD</span></li></ul><p><strong>Endométrite à <span class=\"kw-etio\">SGA</span> <span class=\"q\">— germe le plus redouté</span></strong></p><p><span class=\"kw-ttt\">β-lactamines IV à forte dose</span> ± <span class=\"kw-ttt\">clindamycine</span> ; <span class=\"kw-bio\">hémocultures</span> + test rapide SGA ; avis chirurgical si <span class=\"kw-alerte\">fasciite nécrosante</span> suspectée</p><ul><li>Tableau <span class=\"kw-alerte\">toxinique fulminant</span> en quelques heures</li><li><span class=\"kw-clinique\">Hyperthermie élevée</span> + douleurs intenses + signes cutanés</li><li>Risque de <span class=\"kw-alerte\">choc septique</span></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong> pour toute <span class=\"kw-clinique\">fièvre</span> du post-partum &gt; <span class=\"kw-chiffre\">38,5 °C</span> ou avec <span class=\"kw-alerte\">signes de gravité</span>.<br><strong>Maternité :</strong> endométrite, HPP (tous niveaux) → prise en charge sur place (obstétricien + anesthésiste + sage-femme disponibles).<br><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle de travail</strong> : systématique après tout accouchement, avant tout retour en chambre.<br><strong>Thrombose veineuse cérébrale</strong> : transfert en neurologie/<span class=\"kw-alerte\">réanimation</span> avec <span class=\"kw-imagerie\">IRM cérébrale + angio-IRM</span> veineuse.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Hémorragie &gt; 500 mL</span> ou absence de globe de sécurité utérin</li><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> : <span class=\"kw-clinique\">hypotension</span>, tachycardie, pâleur, <span class=\"kw-clinique\">sueurs</span></li><li><span class=\"kw-alerte\">Fièvre persistante sous ATB</span> → évoquer thrombophlébite pelvienne ou rétention placentaire</li><li><span class=\"kw-alerte\">Purpura ou décollement cutané rapidement évolutif</span> → SGA / S. aureus (<span class=\"kw-alerte\">fasciite nécrosante</span>)</li><li><span class=\"kw-alerte\">Dyspnée brutale</span> en post-partum → <span class=\"kw-alerte\">embolie pulmonaire</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Céphalées inhabituelles</span> + <span class=\"kw-alerte\">convulsions</span> + déficit focal → thrombose veineuse cérébrale</li><li><span class=\"kw-alerte\">CIVD installée</span> : allongement <span class=\"kw-bio\">TP/TCA</span>, effondrement du <span class=\"kw-bio\">fibrinogène</span></li></ul>","principes":"<p>Démarche <strong>étiologique</strong> obligatoire. Trois axes principaux : traitement de l'<span class=\"kw-etio\">hémorragie</span>, traitement de l'<span class=\"kw-clinique\">hyperthermie</span>, traitement de la <span class=\"kw-def\">MTEV</span>.</p><p><strong>Endométrite aiguë</strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> IV pendant <span class=\"kw-chiffre\">5-10 jours</span> (relai per os après normalisation thermique)</li><li><span class=\"kw-ttt\">Utérotoniques</span> (oxytocine, misoprostol) si endométrite <span class=\"kw-etio\">hémorragique</span></li></ul><p><strong>HPP — traitement étiologique (&gt; <span class=\"kw-chiffre\">2 h</span>)</strong></p><ul><li>Atonie : massage utérin + <span class=\"kw-ttt\">utérotoniques</span> · escalade si échec</li><li>Rétention placentaire : révision utérine prudente + <span class=\"kw-ttt\">antibioprophylaxie</span></li><li>Retour de couches <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-ttt\">pilule œstrogénique</span> (en l'absence de <span class=\"kw-ci\">CI</span>)</li></ul><p><strong>MTEV curative</strong></p><ul><li>TVP des MI : <span class=\"kw-ttt\">HBPM curative</span> + contention <span class=\"kw-chiffre\">classe 3</span> · durée <span class=\"kw-chiffre\">3-6 mois</span></li><li>Thrombophlébite pelvienne : <span class=\"kw-ttt\">ATB IV</span> adaptée + <span class=\"kw-ttt\">héparinothérapie curative</span> ± relai <span class=\"kw-ttt\">AVK</span></li><li>TVC : <span class=\"kw-ttt\">HBPM</span> puis relai <span class=\"kw-ttt\">AVK ≥ 6 mois</span> ± mannitol / anti-épileptique</li><li><span class=\"kw-ci\">Fluindione contre-indiquée</span> pendant l'<span class=\"kw-ci\">allaitement</span> — préférer <span class=\"kw-ttt\">warfarine</span> ou <span class=\"kw-ttt\">acénocoumarol</span></li></ul>","suivi":"<p><strong>Post-partum immédiat :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle de travail (<span class=\"kw-clinique\">FC</span> · <span class=\"kw-clinique\">PA</span> · globe utérin · lochies · diurèse).<br><strong>Endométrite :</strong> normalisation thermique attendue <span class=\"kw-chiffre\">48-72 h</span> sous ATB ; si <span class=\"kw-clinique\">fièvre</span> persistante → <span class=\"kw-imagerie\">TDM/IRM</span> pelvienne + <span class=\"kw-imagerie\">échographie</span> (thrombophlébite pelvienne ou rétention ?).<br><strong>Visite postnatale</strong> à <span class=\"kw-chiffre\">6-8 semaines</span> : examen périnéal, prescription <span class=\"kw-ttt\">rééducation périnéale</span>, contraception, <span class=\"kw-def\">dépistage</span> <span class=\"kw-def\">dépression post-partum</span> (EPDS).<br><strong>MTEV :</strong> contrôle écho-<span class=\"kw-imagerie\">doppler veineux</span> à la fin du traitement <span class=\"kw-ttt\">anticoagulant</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Complication des suites de couches — symptôme principal ? — Bilan initial : constantes · examen utérin · lochies · mollets · seins","detail":"<h4>CAT — complications des suites de couches — Démarche diagnostique selon le symptôme principal : <span class=\"kw-clinique\">fièvre</span>, hémorragie génitale ou signes thrombo-emboliques</h4>","branches":[{"to":"q-fievre","label":"Fièvre > 38 °C","color":"amber"},{"to":"q-hemorragie","label":"Hémorragie génitale","color":"red"},{"to":"q-mtev","label":"Signes thrombo-emboliques","color":"red"}]},{"id":"q-fievre","kind":"decision","label":"Contexte de la fièvre ? — Délai par rapport à l'accouchement · signes utérins · seins · voies urinaires","branches":[{"to":"t-montee-laiteuse","label":"J2-J3 · seins tendus bilatéraux · sans autre signe","color":"green"},{"to":"q-endometrite","label":"J3-J5 · douleur à la mobilisation utérine · lochies fétides","color":"amber"},{"to":"t-pna","label":"Signes urinaires · douleur à l'ébranlement lombaire","color":"amber"},{"to":"q-sein","label":"Placard mammaire inflammatoire · sein douloureux","color":"amber"},{"to":"t-infection-site","label":"Infection de cicatrice (abcès paroi / désunion épisiotomie)","color":"amber"}]},{"id":"t-montee-laiteuse","kind":"terminal","label":"Montée laiteuse (diagnostic d'élimination)","color":"green","detail":"<h4>Clinique</h4><ul><li>Fébricule modéré <span class=\"kw-chiffre\">37,5-38 °C</span></li><li>Seins tendus, douloureux bilatéralement</li><li>Pas de douleur utérine, pas de signes urinaires, pas de signe de <span class=\"kw-etio\">TVP</span></li></ul><h4>CAT</h4><ul><li>Pas d'<span class=\"kw-ttt\">ATB</span> — <span class=\"kw-def\">surveillance</span> simple, <span class=\"kw-ttt\">paracétamol</span>, vidange du sein</li></ul><h4>Renvoi</h4><ul><li>Diagnostic d'<strong>élimination</strong> : recontrôler à<span class=\"kw-chiffre\"> 24 h</span> si <span class=\"kw-clinique\">fièvre</span> persistante</li></ul>"},{"id":"q-endometrite","kind":"decision","label":"Sévérité de l'endométrite ? — T° > 38,5 °C ? signes toxiniques ? évolution sous ATB ?","branches":[{"to":"t-endometrite","label":"Tableau habituel — fièvre modérée, pas de signe de gravité","color":"amber"},{"to":"t-thrombophlebite-pelvienne","label":"Fièvre persistante sous ATB de l'endométrite","color":"red"}]},{"id":"t-endometrite","kind":"terminal","label":"Endométrite aiguë du post-partum","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> ≈ <span class=\"kw-chiffre\">38 °C</span> à partir de <span class=\"kw-chiffre\">J3-J5</span></li><li><span class=\"kw-clinique\">Douleur à la mobilisation utérine</span> ⭐ — signe principal</li><li>Lochies <strong>abondantes, malodorantes, fétides</strong></li><li>Utérus mal involué, col béant</li></ul><h4>Germes</h4><ul><li>Infection polymicrobienne : <span class=\"kw-etio\">SGA</span> (le + redouté), entérobactéries, <span class=\"kw-etio\">streptocoque</span> B, entérocoques, anaérobies</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS/CRP</span> · <span class=\"kw-bio\">ECBU</span> · prélèvement vaginal · <span class=\"kw-imagerie\">échographie pelvienne</span> (rétention ?) · <span class=\"kw-bio\">hémocultures</span> si T° &gt; <span class=\"kw-chiffre\">38,5 °C</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span></li><li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> IV pendant <span class=\"kw-chiffre\">5-10 j</span> · relai per os après normalisation</li><li><span class=\"kw-ttt\">Utérotoniques</span> si endométrite <span class=\"kw-etio\">hémorragique</span></li></ul>"},{"id":"t-thrombophlebite-pelvienne","kind":"terminal","label":"Thrombophlébite pelvienne","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Fièvre persistante</span> sous ATB adaptée d'une endométrite</li><li>Douleurs pelviennes / lombo-abdominales diffuses</li><li>Tableau souvent atypique, retardé</li></ul><h4>Paraclinique</h4><ul><li><strong><span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM pelvienne injectée</span></strong> — examen de référence</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">ATB IV adaptée</span> (poursuite ou escalade)</li><li><span class=\"kw-ttt\">Héparinothérapie curative</span> ± relai <span class=\"kw-ttt\">AVK</span> selon localisation et étendue</li></ul>"},{"id":"t-pna","kind":"terminal","label":"Pyélonéphrite aiguë du post-partum","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">frissons</span></li><li>Douleur lombaire unilatérale · <span class=\"kw-clinique\">ébranlement lombaire</span> positif</li><li>Signes fonctionnels urinaires</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-bio\">NFS/CRP</span>, <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-imagerie\">échographie rénale</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">C3G IV</span> (<span class=\"kw-ttt\">céfotaxime</span> / <span class=\"kw-ttt\">ceftriaxone</span>) ± aminoside · durée <span class=\"kw-chiffre\">10-14 j</span>, relai per os adapté à l'<span class=\"kw-bio\">antibiogramme</span></li></ul>"},{"id":"q-sein","kind":"decision","label":"Degré d'atteinte mammaire ?","branches":[{"to":"t-lymphangite","label":"Placard rouge triangulaire · fièvre 39-40 °C · ADP axillaire","color":"amber"},{"to":"t-abces-sein","label":"Tuméfaction fluctuante · fièvre élevée · lait louche","color":"red"}]},{"id":"t-lymphangite","kind":"terminal","label":"Lymphangite mammaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Placard</span> rouge triangulaire unilatéral</li><li><span class=\"kw-clinique\">Fièvre</span> <span class=\"kw-chiffre\">39-40 °C</span></li><li>ADP axillaire homolatérale possible</li></ul><h4>CAT</h4><ul><li>Poursuite de l'<span class=\"kw-ci\">allaitement</span> (sauf <span class=\"kw-clinique\">abcès</span>)</li><li><span class=\"kw-ttt\">ATB anti-staphylococcique</span> (oxacilline / cloxacilline) <span class=\"kw-chiffre\">7-10 j</span></li><li>Tétées fréquentes, vidange complète, <span class=\"kw-ttt\">antalgiques</span> locaux</li></ul>"},{"id":"t-abces-sein","kind":"terminal","label":"Abcès du sein / galactophorite","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-clinique\">fluctuante</span>, <span class=\"kw-clinique\">fièvre</span> élevée</li><li>Signe de Budin positif (lait louche) si galactophorite</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie mammaire</span> — confirme la collection</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Drainage chirurgical</span> ou <span class=\"kw-ttt\">ponction</span> écho-guidée</li><li><span class=\"kw-ttt\">ATB anti-staphylococcique</span></li><li><span class=\"kw-ci\">Allaitement contre-indiqué</span> du côté atteint pendant la phase aiguë</li></ul>"},{"id":"t-infection-site","kind":"terminal","label":"Infection du site opératoire / désunion d'épisiotomie","color":"amber","detail":"<h4>Après césarienne</h4><ul><li><span class=\"kw-ttt\">Évacuation hématome</span> / mise à plat de l'<span class=\"kw-clinique\">abcès</span> de paroi</li><li><span class=\"kw-ttt\">ATB anti-staphylococcique</span> adaptée</li></ul><h4>Après épisiotomie</h4><ul><li>Soins locaux antiseptiques · cicatrisation dirigée · <span class=\"kw-ttt\">reprise chirurgicale</span> différée si nécessaire</li></ul><h4>Alerte</h4><ul><li><span class=\"kw-alerte\">Purpura ou décollement cutané rapidement évolutif</span> → <span class=\"kw-etio\">SGA</span> ou <span class=\"kw-etio\">S. aureus</span> (<span class=\"kw-alerte\">fasciite nécrosante</span>) : <span class=\"kw-ttt\">β-lactamines IV</span> à forte dose + avis chirurgical immédiat</li></ul>"},{"id":"q-hemorragie","kind":"decision","label":"Délai par rapport à l'accouchement ? — Définir la fenêtre temporelle pour orienter l'étiologie","branches":[{"to":"q-hpp-immediate","label":"< 2 h — post-partum immédiat","color":"red"},{"to":"q-hpp-precoce","label":"2-24 h — HPP précoce","color":"amber"},{"to":"q-hpp-tardive","label":"J1 – M3 — HPP tardive / secondaire","color":"amber"}]},{"id":"q-hpp-immediate","kind":"decision","label":"Globe de sécurité utérin présent ?","branches":[{"to":"t-atonie","label":"Non — utérus mou, non rétracté, dépassant l'ombilic","color":"red"},{"to":"t-plaie-filiere","label":"Oui — globe présent · saignement de sang rouge vif","color":"amber"}]},{"id":"t-atonie","kind":"terminal","label":"Atonie utérine (HPP de la délivrance)","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Métrorragies abondantes</span>, sang rouge</li><li><span class=\"kw-alerte\">Absence de globe de sécurité</span> : utérus mou, non rétracté</li><li>Pas de <span class=\"kw-clinique\">fièvre</span>, pas de lochies malodorantes</li></ul><h4>CAT</h4><ul><li>Alerte tous intervenants · monitorage · VVP gros calibre · remplissage</li><li>Délivrance artificielle (si placenta non expulsé) ou révision utérine</li><li><strong>Massage utérin énergique</strong> jusqu'au globe tonique</li><li><span class=\"kw-ttt\">Oxytocine IVL 10 UI</span> renouvelable 1×</li><li>Sac collecteur · sondage urinaire à demeure · suture déchirures</li></ul><h4>Escalade si <span class=\"kw-chiffre\">> 15-30 min</span></h4><ul><li><span class=\"kw-ttt\">Sulprostone</span> seringue électrique · <span class=\"kw-ttt\">acide tranexamique 1 g IV</span></li><li>Embolisation ou <span class=\"kw-ttt\">chirurgie</span> · <span class=\"kw-alerte\">hystérectomie d'hémostase</span> en dernier recours</li></ul>"},{"id":"t-plaie-filiere","kind":"terminal","label":"Plaie de la filière génitale","color":"amber","detail":"<h4>Clinique</h4><ul><li>Saignement de <span class=\"kw-clinique\">sang rouge vif</span></li><li>Utérus bien rétracté (globe de sécurité présent)</li><li>Déchirure du col, du vagin ou du périnée</li></ul><h4>CAT</h4><ul><li><strong>Inspection sous valves systématique</strong> · suture après exposition, au bloc si nécessaire</li></ul>"},{"id":"q-hpp-precoce","kind":"decision","label":"Rétention placentaire à l'échographie ?","branches":[{"to":"t-retention","label":"Oui — image intra-utérine hétérogène","color":"amber"},{"to":"t-atonie-tardive","label":"Non — utérus vide, globe absent ou absent","color":"amber"}]},{"id":"t-retention","kind":"terminal","label":"Rétention placentaire partielle","color":"amber","detail":"<h4>Clinique</h4><ul><li>Pas de signe clinique spécifique — hémorragie persistante malgré utérotoniques</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne</span> ⭐ = examen de référence (cotylédonaires ou membranaires)</li></ul><h4>CAT</h4><ul><li><strong>Révision utérine prudente</strong> (curette mousse sous contrôle échographique — utérus fragile)</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> systématique</li><li>Si hémorragie importante : tamponnement intra-utérin (Bakri) ou embolisation</li></ul>"},{"id":"t-atonie-tardive","kind":"terminal","label":"Atonie utérine tardive (2-24 h)","color":"amber","detail":"<h4>Clinique</h4><ul><li>Métrorragies persistantes · utérus mou, non rétracté · <span class=\"kw-imagerie\">échographie</span> élimine rétention</li></ul><h4>CAT</h4><ul><li>Massage utérin + <span class=\"kw-ttt\">utérotoniques</span> (oxytocine, prostaglandines) · escalade si échec selon protocole HPP</li></ul>"},{"id":"q-hpp-tardive","kind":"decision","label":"Fièvre ou lochies fétides associées ?","branches":[{"to":"t-endometrite-hemo","label":"Oui — tableau infectieux","color":"amber"},{"to":"q-retour-couches","label":"Non — hémorragie isolée, apyrétique, col fermé","color":"green"}]},{"id":"t-endometrite-hemo","kind":"terminal","label":"Endométrite hémorragique","color":"amber","detail":"<h4>Clinique</h4><ul><li>Tableau d'endométrite (<span class=\"kw-clinique\">fièvre</span> · douleur à la mobilisation utérine · lochies fétides) + <span class=\"kw-alerte\">saignement génital</span> surajouté</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> IV</li><li><span class=\"kw-ttt\">Utérotoniques systématiques</span> (oxytocine ± misoprostol)</li></ul>"},{"id":"q-retour-couches","kind":"decision","label":"Délai et profil ?","branches":[{"to":"t-retour-couches","label":"Plusieurs semaines après accouchement · utérus involué · endomètre fin à l'écho","color":"green"},{"to":"t-choriocarcinome","label":"Hémorragie tardive inexpliquée après bilan négatif","color":"red"}]},{"id":"t-retour-couches","kind":"terminal","label":"Retour de couches hémorragique","color":"green","detail":"<h4>Clinique</h4><ul><li>Hémorragie <strong>brutale</strong> plusieurs semaines après l'accouchement</li><li>Cause : <span class=\"kw-etio\">carence œstrogénique</span> ou <span class=\"kw-etio\">contraception microprogestative</span> précoce</li><li>Apyrétique, indolore, col fermé, utérus involué</li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-imagerie\">Utérus vide</span>, endomètre fin · élimine endométrite et rétention</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">Pilule œstrogénique</span> (en l'absence de <span class=\"kw-ci\">contre-indication</span>) · <span class=\"kw-def\">surveillance</span> simple si pertes modérées</li></ul>"},{"id":"t-choriocarcinome","kind":"terminal","label":"Choriocarcinome (à éliminer)","color":"red","detail":"<h4>Clinique</h4><ul><li>Hémorragie tardive <strong>inexpliquée</strong> malgré bilan initial négatif</li></ul><h4>Paraclinique</h4><ul><li><strong>Dosage <span class=\"kw-bio\">hCG</span> systématique</strong></li></ul><h4>CAT</h4><ul><li>Orientation oncologique spécialisée si hCG positif (<span class=\"kw-ttt\">chimiothérapie</span>)</li></ul>"},{"id":"q-mtev","kind":"decision","label":"Localisation des signes ? — Post-partum = FR transitoire majeur de MTEV (8 premières semaines ++)","branches":[{"to":"t-tvp","label":"Douleur de mollet unilatérale · œdème · signe de Homans","color":"amber"},{"to":"t-ep","label":"Dyspnée brutale · douleur thoracique · tachycardie · hypoxémie","color":"red"},{"to":"t-tvc","label":"Céphalées inhabituelles · convulsions · déficit focal · HTIC","color":"red"}]},{"id":"t-tvp","kind":"terminal","label":"Thrombose veineuse profonde (MI)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Douleur de mollet unilatérale</span></li><li><span class=\"kw-clinique\">Œdème</span>, augmentation du <span class=\"kw-clinique\">diamètre</span>, perte du ballant</li><li>Signe de Homans · fébricule · <span class=\"kw-clinique\">tachycardie</span> inexpliquée</li></ul><h4>Paraclinique</h4><ul><li><strong>Écho-<span class=\"kw-imagerie\">doppler veineux</span> des MI</strong> · <span class=\"kw-bio\">D-dimères</span> <em>peu utiles en PP</em> (élevés physiologiquement)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">HBPM curative</span> + contention veineuse <span class=\"kw-chiffre\">classe 3</span></li><li>Durée <span class=\"kw-chiffre\">3-6 mois</span> · relai <span class=\"kw-ttt\">AVK</span> compatible <span class=\"kw-ci\">allaitement</span> (<span class=\"kw-ci\">pas de fluindione</span>)</li></ul>"},{"id":"t-ep","kind":"terminal","label":"Embolie pulmonaire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Dyspnée brutale</span> · <span class=\"kw-clinique\">douleur thoracique</span> · <span class=\"kw-clinique\">tachycardie</span></li><li><span class=\"kw-alerte\">Toute dyspnée du post-partum = EP jusqu'à preuve du contraire</span></li></ul><h4>Paraclinique</h4><ul><li><strong><span class=\"kw-imagerie\">Angio-TDM thoracique</span></strong> (<span class=\"kw-imagerie\">scintigraphie V/Q</span> si <span class=\"kw-ci\">contre-indication</span>)</li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">HBPM curative</span> immédiate · relai <span class=\"kw-ttt\">AVK</span> · <span class=\"kw-alerte\">hospitalisation</span></li></ul>"},{"id":"t-tvc","kind":"terminal","label":"Thrombose veineuse cérébrale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées</span> inhabituelles, persistantes</li><li><span class=\"kw-alerte\">Crises convulsives</span> · <span class=\"kw-alerte\">déficit focal</span> · troubles de conscience</li></ul><h4>Paraclinique</h4><ul><li><strong><span class=\"kw-imagerie\">IRM cérébrale</span> + <span class=\"kw-imagerie\">angio-IRM veineuse</span></strong></li></ul><h4>CAT</h4><ul><li><span class=\"kw-ttt\">HBPM curative</span> puis relai <span class=\"kw-ttt\">AVK ≥ 6 mois</span></li><li>± mannitol / anti-épileptique selon signes neurologiques</li><li>Transfert neurologie / <span class=\"kw-alerte\">réanimation</span></li></ul>"}]},"cards":[{"i":"3338deabf3ff","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quels sont les éléments cliniques et paracliniques suggestifs d'une endométrite hémorragique comme cause d'HPP tardive ?","a":"<ul><li><strong>Clinique :</strong> tableau d'endométrite avec <strong>fièvre</strong>, <strong>douleur à la mobilisation utérine</strong>, <strong>lochies fétides</strong>, auxquels s'ajoute un saignement génital.</li><li><strong>Paraclinique :</strong> une <strong>NFS/CRP</strong>, un <strong>prélèvement vaginal</strong> et une <strong>échographie pelvienne</strong> (pour rechercher une rétention) sont réalisés.</li></ul>"},{"i":"53583d2f59fe","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Dans le contexte d'une hémorragie tardive inexpliquée après l'accouchement, quel dosage paraclinique doit être systématiquement réalisé et pourquoi ?","a":"<p>Un <strong>dosage de l'hCG</strong> (hormone chorionique gonadotrophine) doit être systématiquement réalisé afin d'éliminer la piste d'un <strong>choriocarcinome</strong>, une cause rare d'hémorragie tardive.</p>"},{"i":"5fe4d8c8326e","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Face à une rétention placentaire partielle causant une HPP, quels sont les signes cliniques et le principal examen paraclinique à réaliser ?","a":"<ul><li><strong>Clinique :</strong> il n'y a pas de signe clinique spécifique. L'hémorragie persiste malgré les utérotoniques et peut favoriser une atonie ou une endométrite.</li><li><strong>Paraclinique :</strong> l'<strong>échographie pelvienne</strong> est l'examen de référence, systématique en cas d'hyperthermie ou d'hémorragie du post-partum.</li></ul>"},{"i":"9299c7f09f52","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Comment définit-on une hémorragie du post-partum (HPP) et quelle est son importance épidémiologique en France ?","a":"<p>Une HPP est définie par une <strong>perte sanguine ≥ 500 mL</strong> dans les suites de couches. C'est la <strong>première cause de mortalité maternelle en France</strong>, évitable dans 80 à 90 % des cas.</p>"},{"i":"a45128e9a9bd","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quelles sont les trois fenêtres temporelles distinctes pour une hémorragie du post-partum et leurs causes dominantes associées ?","a":"<ul><li><strong>Hémorragie de la délivrance</strong> (post-partum immédiat &lt; 2h) : l'<strong>atonie utérine</strong> est la cause dominante (&gt; 50%).</li><li><strong>HPP précoce</strong> (entre 2h et 24h) : <strong>atonie utérine</strong>, <strong>rétention placentaire partielle</strong> (cotylédons, membranes) et <strong>plaie de la filière génitale</strong>.</li><li><strong>HPP tardive/secondaire</strong> (entre J1 et M3) : <strong>endométrite hémorragique</strong>, <strong>retour de couches hémorragique</strong>, et plus rarement un <strong>choriocarcinome</strong>.</li></ul>"},{"i":"afb4cb0a6789","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Comment diagnostique-t-on une HPP due à une plaie de la filière génitale ?","a":"<ul><li><strong>Clinique :</strong> <strong>saignement de sang rouge vif</strong> avec un <strong>utérus bien rétracté</strong> (globe de sécurité présent).</li><li><strong>Examen clé :</strong> une <strong>inspection sous valves systématique des voies génitales basses</strong> (déchirure du col, du vagin, du périnée) est indispensable.</li></ul>"},{"i":"e1f4ea1e8580","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quels sont les signes cliniques et l'examen paraclinique clé en présence d'une atonie utérine post-partum ?","a":"<ul><li><strong>Clinique :</strong> <strong>métrorragies abondantes</strong> de sang rouge, <strong>absence de globe de sécurité</strong> (utérus mou, non rétracté, dépassant l'ombilic), pas de fièvre ni de lochies malodorantes.</li><li><strong>Paraclinique :</strong> une <strong>échographie pelvienne</strong> est réalisée pour éliminer une rétention (membranes, cotylédons).</li></ul>"},{"i":"284b182f3dbe","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Pourquoi les D-dimères n'ont-ils pas de valeur d'exclusion pour une MTEV en post-partum ?","a":"<p>Les D-dimères sont <strong>physiologiquement élevés</strong> pendant le post-partum, ce qui en fait un examen sans valeur d'exclusion. La décision diagnostique repose donc directement sur la <strong>probabilité clinique</strong> et l'<strong>imagerie appropriée</strong> (écho-Doppler veineux, angio-TDM, TDM/IRM pelvienne ou IRM/angio-IRM cérébrale selon le cas).</p>"},{"i":"3618bd988020","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quelle est la complication majeure de la thrombose veineuse en post-partum et comment la diagnostiquer ?","a":"<p>La complication redoutée est l'<strong>embolie pulmonaire (EP)</strong>. Toute <strong>dyspnée brutale</strong>, <strong>douleur thoracique</strong>, <strong>tachycardie</strong> ou <strong>hypoxémie</strong> du post-partum doit être considérée comme une EP jusqu'à preuve du contraire. La confirmation repose sur l'<strong>angio-TDM thoracique</strong>, ou une <strong>scintigraphie de ventilation/perfusion (V/Q)</strong> en cas de contre-indication au scanner.</p>"},{"i":"6207f4cc1747","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quand suspecter une thrombophlébite pelvienne dans le post-partum et comment la diagnostiquer ?","a":"<p>Une thrombophlébite pelvienne doit être suspectée devant une <strong>fièvre persistante</strong> malgré un traitement antibiotique pour une endométrite, associée à des <strong>douleurs pelviennes / lombo-abdominales diffuses</strong>. Le tableau clinique est souvent atypique et retardé. Le diagnostic est confirmé par <strong>TDM ou IRM pelvienne injectée</strong>.</p>"},{"i":"6c2f5c88ba6e","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels sont les facteurs de risque spécifiques de la maladie thromboembolique veineuse (MTEV) dans le post-partum ?","a":"<p>Les facteurs de risque incluent :</p><ul><li>Âge <strong>supérieur à 35 ans</strong>, <strong>multiparité</strong>, <strong>tabac</strong>.</li><li><strong>Obésité</strong>, <strong>varices</strong>, affections cardiaques.</li><li>Antécédents personnels de MTEV, <strong>thrombophilie</strong>.</li><li>Accouchement <strong>dystocique</strong> ou <strong>césarienne</strong> (surtout en urgence).</li><li>Procréation médicalement assistée.</li><li>Hémorragie du post-partum.</li></ul><p>Le post-partum est un facteur de risque majeur transitoire, surtout pendant les <strong>8 premières semaines</strong>.</p>"},{"i":"7e19062ce745","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels sont les signes cliniques orientant vers une thrombose veineuse profonde (TVP) des membres inférieurs dans le post-partum et quel est l'examen de référence ?","a":"<p>Les signes cliniques sont :</p><ul><li><strong>Douleur du mollet unilatérale</strong>.</li><li><strong>Œdème</strong>, <strong>augmentation du diamètre</strong> de la jambe, <strong>perte du ballant</strong> du mollet.</li><li>Signe de <strong>Homans</strong>.</li><li>Fébricule modéré, tachycardie inexpliquée.</li></ul><p>L'examen de référence est l'<strong>écho-Doppler veineux des membres inférieurs</strong>. Il est important de noter que les <strong>D-dimères sont peu utiles</strong> dans cette situation car physiologiquement élevés en post-partum.</p>"},{"i":"871e6781955f","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels signes cliniques évoquent une thrombose veineuse cérébrale dans le post-partum et quel est l'examen diagnostique clé ?","a":"<p>Les signes cliniques évocateurs sont des <strong>céphalées inhabituelles et persistantes</strong>, des <strong>crises convulsives</strong>, un <strong>déficit neurologique focal</strong>, des troubles de la conscience ou des signes d'hypertension intracrânienne (<strong>HTIC</strong>). L'examen diagnostique clé est l'<strong>IRM cérébrale</strong> associée à une <strong>angio-IRM veineuse</strong>.</p>"},{"i":"b38b24ecbdde","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Comment diagnostiquer une thrombose veineuse superficielle (TVS) dans le post-partum ?","a":"<p>La TVS se manifeste par un <strong>cordon induré douloureux</strong> sur un trajet variqueux, avec une <strong>inflammation locale</strong> et <strong>pas de fièvre élevée</strong>. Le diagnostic est principalement <strong>clinique</strong>, confirmé par un <strong>écho-Doppler veineux</strong> qui permet d'éliminer une extension profonde.</p>"}]};